import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper submits the order. If it fails a corresponding Error interaction should be sent.
*/
export type CheckoutSubmit = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutSubmitBuilder {

    private checkoutSubmit: CheckoutSubmit = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutSubmitBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutSubmitBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutSubmitBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutSubmitBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutSubmit {
        if(this.cart) {
            this.checkoutSubmit.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutSubmit.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutSubmit.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutSubmit.events.push(this.partyIdentification);
        }

        return this.checkoutSubmit;
    }
}
